#!/usr/bin/env node
// Generate src/app/context-menu/wordlist.ts (offline English word list for the
// renderer-side spell-check suggestions).
//
// Sources (Debian packages installed at build time):
//   - /usr/share/hunspell/en_US.dic  (package hunspell-en-us)
//   - /usr/share/dict/american-english (package wamerican)
// Both derive from SCOWL (Spell Checker Oriented Word Lists) by Kevin
// Atkinson and contributors; see the license header this script writes into
// the generated file, which reproduces the SCOWL permission notice from
// /usr/share/doc/hunspell-en-us/copyright and /usr/share/doc/wamerican/copyright.
// Hunspell .dic entries carry affix/morphology flags after "/" which are
// stripped; the American-English list supplies fully inflected forms that
// hunspell only covers through affix rules.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const SRC_CANDIDATES = [
  '/usr/share/hunspell/en_US.dic',
  '/usr/share/hunspell/en-us.dic',
  '/usr/share/myspell/dicts/en_US.dic'
]
const OUT = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'app', 'context-menu', 'wordlist.ts')

const src = SRC_CANDIDATES.find(p => {
  try {
    readFileSync(p)
    return true
  } catch {
    return false
  }
})

if (!src) {
  console.error('No source dict found at:', SRC_CANDIDATES.join(', '))
  process.exit(1)
}

// Chemical-element symbols leak into the hunspell list as standalone entries
// (Te, Th, Fe, …). Lowercased they look like 2–3 letter "words" that only
// produce junk suggestions — drop them. This is the standard periodic-table
// set (1–3 letter caseless codes).
const ELEMENTS = new Set(
  `h he li be b c n o f ne na mg al si p s cl ar k ca sc ti v cr mn fe co ni cu zn ga ge as se br kr
   rb sr y zr nb mo tc ru rh pd ag cd in sn sb te i xe cs ba la ce pr nd pm sm eu gd tb dy ho er tm
   yb lu hf ta w re os ir pt au hg tl pb bi po at rn fr ra ac th pa u np pu am cm bk cf es fm md no
   lr rf db sg bh hs mt ds rg cn nh fl mc lv ts og`.split(/\s+/)
)

const raw = readFileSync(src, 'utf8')
const words = new Set()

/** Normalize + admit a single dictionary word into the set. */
function admit(wordRaw) {
  let word = wordRaw.split('/')[0].split(':')[0].trim()
  if (!word) return
  // Keep letters + apostrophes only
  if (!/^[A-Za-z][A-Za-z''’]*$/.test(word)) return
  const lower = word.toLowerCase().replace(/[’]/g, "'")
  if (lower.length > 24) return
  // Keep single letters only for a/i (common words)
  if (lower.length === 1 && lower !== 'a' && lower !== 'i') return
  // Drop chemical element symbols (Te, Th, Fe, Pt, …) — but keep the handful
  // that are also common English function words (he, be, as, at, no, in) and
  // the pronoun "i" (iodine's symbol).
  if (ELEMENTS.has(lower) && !['he', 'be', 'as', 'at', 'no', 'in', 'i'].includes(lower)) return
  words.add(lower)
}

// Source 1: hunspell en_US stem dictionary (comprehensive stems + flag rules).
for (const line of raw.split(/\r?\n/)) {
  const entry = line.trim()
  if (!entry || entry.startsWith('#')) continue
  admit(entry)
}

// Source 2: system American-English word list (includes fully inflected forms
// like "remove" / "removes" / "removing", which hunspell only covers via affix
// rules that a stem list cannot reconstruct).
const WORDLIST_CANDIDATES = ['/usr/share/dict/american-english', '/usr/share/dict/words']
const dict2 = WORDLIST_CANDIDATES.find(p => {
  try {
    readFileSync(p)
    return true
  } catch {
    return false
  }
})

if (dict2) {
  for (const line of readFileSync(dict2, 'utf8').split(/\r?\n/)) {
    const entry = line.trim()
    if (!entry || entry.startsWith('#')) continue
    admit(entry)
  }
}

const sorted = [...words].sort()
const body = sorted.map(w => `  ${JSON.stringify(w)},`).join('\n')

const out = `// AUTOGENERATED — do not edit by hand.
// Offline English word list for renderer-side spell-check suggestions.
// Regenerate: node scripts/generate-wordlist.mjs  (sources: ${src}${dict2 ? ` + ${dict2}` : ''})
// ${sorted.length} unique words.
//
// WORD DATA LICENSE
// -----------------
// Generated from two Debian packages installed at build time:
//   - ${src}  (package: hunspell-en-us)
//   - ${dict2 ?? '(none)'}  (package: wamerican)
// Both derive from SCOWL (Spell Checker Oriented Word Lists),
// Copyright (C) 2000-2011 by Kevin Atkinson <kevina@users.sourceforge.net>
// and other contributors (see /usr/share/doc/hunspell-en-us/copyright and
// /usr/share/doc/wamerican/copyright). The operative permission notice,
// quoted from those files, is:
//
//   Permission to use, copy, modify, distribute and sell these word lists,
//   the associated scripts, the output created from the scripts, and its
//   documentation for any purpose is hereby granted without fee, provided
//   that the above copyright notice appears in all copies and that both
//   that copyright notice and this permission notice appear in supporting
//   documentation. Kevin Atkinson makes no representations about the
//   suitability of this array for any purpose. It is provided "as is"
//   without express or implied warranty.
//
// Individual components within SCOWL are public domain where noted (Moby
// lexicon project, UK English Wordlist With Frequency Classification,
// 12Dicts / ENABLE word lists), per the package copyright files.
export const wordList: readonly string[] = [
${body}
]
`

writeFileSync(OUT, out)
console.log(`Generated ${OUT}`)
console.log(`Words: ${sorted.length} (source: ${src}${dict2 ? ` + ${dict2}` : ''})`)
